raw = state.get('entities_raw') or ''
text = state.get('text') or ''
out = {}
for line in str(raw).splitlines():
    line = line.strip()
    if not line or line.upper() == 'NONE' or '|' not in line:
        continue
    etype, name = line.split('|', 1)
    etype = etype.strip()
    name = name.strip()
    if not etype or not name or name.upper() == 'NONE':
        continue
    if name not in text:
        continue
    out.setdefault(etype, [])
    if name not in out[etype]:
        out[etype].append(name)
__result__ = out
